(() => {
'use strict';
const $ = (s, root=document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='learnflow.v1';
const initial=()=>({version:1,profile:{goal:'',minutes:25,guide:'gentle',style:'plain',encourage:'quiet',memory:false},adopted:['roots','plain'],favorites:[],ratings:{},usage:{},custom:[],memories:[],sessions:[],blocks:0,tasks:[],scene:'exam',onboarded:false});
let state=initial(), storageOK=true;
try {const saved=JSON.parse(localStorage.getItem(KEY)||'null'); if(saved?.version===1)state={...initial(),...saved,profile:{...initial().profile,...saved.profile}};}catch{storageOK=false;}
let page='home', filter='all', query='', activeSession=null, mode='demo', apiStatus=null, busy=false, activeRequest=null, retryRequest=null, guideStep=0, guideDraft={}, toastTimer;
const sessionPool=new Map(),sessionDrafts=new Map(),queuedPaint=new WeakSet();let renderedSession=null,chatScroll=null;
const chatPage=()=>page==='home'||page==='session';
const icons={home:'M3 10 12 3 21 10M5 9v11h14V9M9 20v-7h6v7',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',layers:'m12 3 9 5-9 5-9-5 9-5ZM3 12l9 5 9-5M3 16l9 5 9-5',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5ZM9 3v16M15 5v16',plug:'M9 3v5M15 3v5M6 8h12v3a6 6 0 0 1-12 0V8ZM12 17v4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',scan:'M8 3H3v5M16 3h5v5M21 16v5h-5M8 21H3v-5M7 9h10M7 13h10M7 17h6',sprout:'M12 21V10M12 14C4 14 3 10 3 5c7 0 9 3 9 9ZM12 10c0-5 3-7 9-7 0 6-3 9-9 9',message:'M21 11a9 9 0 0 1-9 9H4l-3 2 2-6a9 9 0 1 1 18-5ZM7 10h10M7 14h6',compass:'M21 12a9 9 0 1 0-18 0 9 9 0 0 0 18 0ZM16 8l-3 5-5 3 3-5 5-3Z',type:'M4 4h16M12 4v16M8 20h8',clipboard:'M9 4H5v17h14V4h-4M9 2h6v4H9zM8 11h8M8 15h5',arrow:'M5 12h14M14 7l5 5-5 5',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z',clock:'M21 12a9 9 0 1 0-18 0 9 9 0 0 0 18 0ZM12 7v5l3 2'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.spark}"/></svg>`;
const cards=()=>[...window.LF_CARDS,...state.custom];
const cardBy=id=>cards().find(c=>c.id===id);
const activeCards=(scene=state.scene)=>cards().filter(c=>state.adopted.includes(c.id)&&(c.scene==='all'||c.scene===scene));
const fmt=n=>Number(n||0).toLocaleString('zh-CN');
const totalUsage=kind=>Object.values(state.usage).reduce((a,u)=>a+Number(u[kind]||0),0);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('浏览器未能保存数据，请立即导出备份。');}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3900);}
function download(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function showModal(content){$('#modal-content').innerHTML=content;if(!$('#modal').open)$('#modal').showModal();}
const modalHead=title=>`<div class="modal-head"><h2>${esc(title)}</h2><button class="close" data-action="close" aria-label="关闭">×</button></div>`;
const navs=[['market','grid','策略广场'],['assets','clipboard','学习资料'],['project','map','任务看板'],['classroom','clipboard','课程空间']];
function navigate(target){if(target===page&&location.hash==='#'+target){render();return}location.hash=target;}

function render(){
 const route=(location.hash.slice(1)||'home').split('?')[0];page=route.split('/')[0];
 const legacy={connectors:'connections',mine:'learning',memory:'memory',teacher:'teacher',about:'about'};
 if(legacy[page]){location.hash='settings/'+legacy[page];return;}
 if(!['home','market','assets','project','settings','session','classroom'].includes(page))page='home';
 const old=$('#messages'),oldInput=$('#chat-input'),hadFocus=oldInput===document.activeElement;
 if(old&&renderedSession===activeSession?.id)chatScroll={id:renderedSession,top:old.scrollTop,bottom:old.scrollHeight-old.scrollTop-old.clientHeight<110};
 const selection=hadFocus?[oldInput.selectionStart,oldInput.selectionEnd]:null;
 gallery.dispose();teacherDemo.dispose();document.body.classList.toggle('is-market',page==='market');document.body.classList.toggle('is-chat',chatPage());document.body.classList.toggle('is-settings',page==='settings');
 $('#navigation').innerHTML=navs.map(([id,ic,label])=>`<a href="#${id}" class="nav-item ${page===id?'active':''}">${icon(ic)}<span>${label}</span></a>`).join('');
 $('#page-label').textContent=chatPage()?(activeSession?.title||'LearnFlow'):navs.find(n=>n[0]===page)?.[2]||'设置';
 $('#main').innerHTML=({home:homeView,session:sessionView,assets:()=>experience.assetsView(),market:marketView,project:projectView,classroom:()=>teacherDemo.view(location.hash),settings:()=>settingsUI.view(route.split('/')[1]||'general')}[page])();
 $('.sidebar').classList.remove('open');document.body.classList.remove('nav-open');closeProfile();renderHistory();
 if(page==='settings')settingsUI.mount();
 if(page==='classroom')teacherDemo.mount();
 if(page==='market')gallery.mount(marketCards(),{filter,query});
 if(chatPage()){
  window.LearnFlowComposer?.mount(mode,busy);renderedSession=activeSession?.id;
  const box=$('#messages');if(box){if(chatScroll?.id===renderedSession&&!chatScroll.bottom)box.scrollTop=chatScroll.top;else box.scrollTop=box.scrollHeight;}
  if(hadFocus&&$('#chat-input')){$('#chat-input').focus({preventScroll:true});if(selection)$('#chat-input').setSelectionRange(...selection);}
 }
 if(!storageOK)toast('本机存储暂不可用；请使用导出备份。');
}
function sessionTitle(s){return s.title||s.messages.find(m=>m.role==='user')?.content.slice(0,32)||'新对话';}
function allSessions(){const list=new Map(state.sessions.map(s=>[String(s.id),s]));sessionPool.forEach((s,id)=>list.set(String(id),s));if(activeSession?.messages.length)list.set(String(activeSession.id),activeSession);return [...list.values()].filter(s=>s.messages.length).sort((a,b)=>Number(b.id)-Number(a.id));}
function renderHistory(){
 workspaceSidebar.render($('#session-history')).catch(()=>toast('暂时没有显示项目分组，请刷新后重试。'));

}
function closeProfile(){const menu=$('#profile-menu');if(menu)menu.hidden=true;$('.profile')?.setAttribute('aria-expanded','false');}
function stashDraft(){if(activeSession)sessionDrafts.set(String(activeSession.id),{text:window.LearnFlowComposer?.draft?.()||'',files:[...(window.LearnFlowComposer?.files()||[])]});}
function openSession(id){if(busy)return toast('先停止当前回答，再切换对话。');if(String(activeSession?.id)===String(id)){closeProfile();$('#modal').close();navigate('session');return;}const s=allSessions().find(s=>String(s.id)===String(id));if(!s)return;stashDraft();activeSession=structuredClone(s);sessionPool.set(activeSession.id,activeSession);state.scene=s.scene;window.LearnFlowComposer?.reset();const draft=sessionDrafts.get(String(id));if(draft)window.LearnFlowComposer?.restore(draft.files,draft.text);retryRequest=null;chatScroll=null;$('#modal').close();navigate('session');}
function searchChats(){showModal(modalHead('搜索对话')+'<input class="search chat-search" id="chat-search" placeholder="输入标题或聊过的内容" aria-label="搜索对话内容"><div id="chat-search-results"></div>');const draw=()=>{const q=$('#chat-search').value.toLowerCase();$('#chat-search-results').innerHTML=allSessions().filter(s=>(sessionTitle(s)+' '+s.messages.map(m=>m.content).join(' ')).toLowerCase().includes(q)).map(s=>`<button class="search-chat-result" data-session="${esc(s.id)}">${icon('message')}<span>${esc(sessionTitle(s))}<small>${new Date(s.created).toLocaleDateString('zh-CN')} · ${LF_SCENES[s.scene]?.title||'学习'}</small></span>${icon('arrow')}</button>`).join('')||'<p class="search-empty">还没有找到相关对话</p>';};$('#chat-search').oninput=draw;draw();$('#chat-search').focus();}
function learningOptions(){showModal(modalHead('这次怎么学')+`<div class="learning-options"><p>用顺手的方法，学完一小段再决定要不要换。</p><div class="scene-pills">${Object.entries(LF_SCENES).map(([id,s])=>`<button data-current-scene="${id}" class="${state.scene===id?'selected':''}">${icon(s.icon)}${s.title}</button>`).join('')}</div><h3>正在用的方法</h3>${cards().filter(c=>c.scene==='all'||c.scene===state.scene).map(c=>`<label class="method-toggle"><span><strong>${esc(c.title.split(' · ')[0])}</strong><small>${esc(c.description)}</small></span><input type="checkbox" class="toggle" data-method-toggle="${esc(c.id)}" ${state.adopted.includes(c.id)?'checked':''}></label>`).join('')}<div class="button-row"><a class="secondary" href="#market" data-action="browse-methods">去策略广场</a><button class="primary" data-action="close">就这样开始</button></div></div>`);}
function chatOptions(){showModal(modalHead('对话选项')+`<div class="option-list"><button data-action="rename-chat">${icon('type')}重命名对话</button><button data-action="export-chat">${icon('clipboard')}导出这段对话</button><button data-action="complete-block">${icon('layers')}整理当前学习块</button><button data-action="onboard">${icon('compass')}调整学习路线</button><a href="#settings/general" data-action="open-settings">${icon('settings')}设置</a></div>`);}
function cardView(c,personal=false){const adopted=state.adopted.includes(c.id),u=state.usage[c.id]||{};return `<article class="strategy-card"><div class="card-top"><button class="symbol ${esc(c.color||'orange')}" data-detail="${esc(c.id)}" aria-label="查看${esc(c.title)}">${icon(c.icon)}</button><button class="fav ${state.favorites.includes(c.id)?'on':''}" data-favorite="${esc(c.id)}" aria-label="${state.favorites.includes(c.id)?'取消收藏':'收藏'}${esc(c.title)}">${state.favorites.includes(c.id)?'★':'☆'}</button></div><button data-detail="${esc(c.id)}" style="text-align:left;padding:0"><h3>${esc(c.title)}</h3></button><p class="description">${esc(c.description)}</p><div class="tags">${c.tags.slice(0,3).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>${personal?`<div class="progress"><i style="width:${Math.min(100,(u.estimated||0)/25)}%"></i></div><div class="token-note">真实分摊 ${fmt(u.actual)} tokens · 演示估算 ${fmt(u.estimated)}</div>`:''}<div class="card-bottom"><span>${state.ratings[c.id]?`★ ${state.ratings[c.id]} · 我的评分`:'团队预设 · 可编辑'}</span><button class="adopt ${adopted?'selected':''}" data-adopt="${esc(c.id)}">${adopted?'✓ 已启用':'+ 采纳策略'}</button></div></article>`;}
function head(title,sub,extra=''){return `<div class="page-head"><div><h1>${title}</h1></div>${extra}</div>`;}

function homeView(){return sessionView();}
function marketView(){return gallery.view();}
function marketCards(){return cards().filter(c=>(filter==='all'||(filter==='favorite'?state.favorites.includes(c.id):filter==='style'?c.scene==='all':c.scene===filter))&&`${c.title} ${c.description} ${c.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase()));}
function mineView(){return head('我的学习策略','正在用的方法都在这里。点开可查看步骤，也能停用或导出。',`<button class="secondary" data-action="export-strategies">导出已启用策略</button>`)+`<div class="metrics"><div class="metric"><span>正在使用的策略</span><strong>${state.adopted.length}<small> 张</small></strong></div><div class="metric"><span>接口报告 Token 总量</span><strong>${fmt(totalUsage('actual'))}</strong></div><div class="metric"><span>完成的学习块</span><strong>${state.blocks}</strong></div></div><details class="ui-help"><summary>用量与评分说明</summary><p>演示估算：${fmt(totalUsage('estimated'))} tokens，与真实接口用量分开保存。卡片个人评分的使用权重为 min(1, log(1+真实分摊量) / log(10001))；本地仅展示本人评分，不生成虚假的社区排行。学习效果需看迁移题、延迟测验和实际产出。</p></details><div class="card-grid market-grid">${cards().filter(c=>state.adopted.includes(c.id)).map(c=>cardView(c,true)).join('')||'<div class="empty">还没有启用策略。去策略广场选一张试试。</div>'}</div>`;}
function ensureSession(){if(!activeSession){const previous=state.profile.memory?state.sessions.at(-1):null;activeSession=previous?structuredClone(previous):{id:Date.now(),scene:state.scene,messages:[],completed:false,created:new Date().toISOString()};state.scene=activeSession.scene;}return activeSession;}

function sessionView(){const s=ensureSession(),hasMessages=s.messages.length>0;const starts={exam:[['复盘一道错题','我想复盘一道错题，先帮我找判断依据。'],['用词根记单词','用词根词缀背单词，输出表格'],['来一轮自测','给我一道主动回忆练习']],self:[['把概念讲明白','先用费曼法理解一个概念'],['从哪里开始学','我想建立一周的自学路线'],['检查我是否理解','请问我一个问题，检查我是否真正理解刚学的内容。']],project:[['拆解一个想法','帮我把项目想法拆成可执行的第一步'],['画一张学习地图','帮我梳理项目需要先学会什么'],['检查阶段成果','如何验证我们的项目有效']]};return `<section class="chat-workspace ${hasMessages?'has-messages':'empty-chat'}" aria-label="学习对话"><div class="messages" id="messages" aria-label="对话记录">${hasMessages?`<div class="message-column">${s.messages.map(messageView).join('')}</div>`:''}</div>${!hasMessages?`<div class="chat-welcome"><img src="./assets/learnflow-logo.svg" alt="" class="welcome-logo"><h1>今天，想弄懂什么？</h1><div class="scene-pills" aria-label="选择学习场景">${Object.entries(LF_SCENES).map(([id,scene])=>`<button type="button" data-current-scene="${id}" class="${s.scene===id?'selected':''}" aria-pressed="${s.scene===id}">${icon(scene.icon)}${scene.title}</button>`).join('')}</div></div>`:''}<div class="composer-dock"><div class="learning-context"><button data-action="learning-options" title="调整当前学习方法">${icon('layers')}<span>${activeCards().slice(0,2).map(c=>esc(c.title.split(' · ')[0])).join(' + ')||'选择学习方法'}</span><span class="context-chevron">⌄</span></button><button data-action="study-time" title="调整学习时长">${icon('clock')}${state.profile.minutes} 分钟</button></div><form id="chat-form" class="prompt-box"><textarea id="chat-input" rows="2" aria-label="学习对话输入" placeholder="说说你的问题，或拖入图片、文件…"></textarea><div class="prompt-bottom"><div class="prompt-hints"></div>${busy?'<button class="send stop-send" data-action="stop-chat" aria-label="停止生成" type="button"><span></span></button>':'<button class="send" aria-label="发送消息" type="submit"><svg viewBox="0 0 24 24"><path d="M12 19V5M5 12l7-7 7 7"/></svg></button>'}</div></form>${!hasMessages?`<div class="starter-prompts">${starts[s.scene].map(([label,prompt])=>`<button data-prompt="${esc(prompt)}">${label}<span>↗</span></button>`).join('')}</div>`:''}</div></section>`;}
function usageReceipt(m){
 const number=value=>Number.isFinite(value)&&value>=0?fmt(value):'未提供';
 const demo=m.usage.source==='estimated';
 const actual=!demo&&Number.isFinite(m.usage.actual)&&m.usage.actual>=0;
 const summary=actual?`${number(m.usage.actual)} Tokens · 用量与积分`:m.usage.source==='estimated'?'演示用量':'用量与积分';
 const provider=m.providerUsage||{};
 return `<details class="reply-receipt"><summary>${summary}</summary><dl class="usage-grid"><dt>调用入口</dt><dd>${esc(m.clientName||m.source||'模型服务')}</dd><dt>实际模型</dt><dd>${esc(m.model||'未提供')}</dd><dt>${demo?'演示估算':'本轮 Token'}</dt><dd>${number(demo?m.usage.estimated:m.usage.actual)}</dd>${!demo?`<dt>输入 / 输出</dt><dd>${number(provider.prompt_tokens)} / ${number(provider.completion_tokens)}</dd><dt>本轮积分</dt><dd>当前通道未提供</dd><dt>账号余额</dt><dd>当前通道未提供</dd>`:''}</dl><p>${demo?'演示未调用模型，不产生模型费用。':esc(m.billing?.note||'该记录没有积分账单；实际扣费请在客户端或模型服务商处查看。')}${m.usage.source==='restored'?' 此记录来自备份，未经重新验证。':''}</p>${m.receipt?`<p class="usage-request">调用编号：${esc(m.receipt.requestId)}</p>`:''}</details>`;
}
function messageView(m,index){
 const live=m.streaming, label=m.role==='user'?'你':m.error?(m.stopped?'已停止':'这次没收到完整回答'):m.source?.startsWith('授权接口')?'LearnFlow'+(m.model?' · '+m.model:''):m.source||'LearnFlow';
 return `<div class="message ${m.role==='user'?'user':''} ${m.error?'message-error':''}" data-message-index="${index}" ${live?'aria-busy="true"':''}><span class="msg-label">${m.role==='assistant'?'<img src="./assets/learnflow-logo.svg" alt="">':''}${esc(label)}</span><div class="message-content ${m.role==='assistant'?'rich-text':''}">${m.role==='assistant'?window.LearnFlowText.render(live?window.LearnFlowText.visibleStream(m.content):m.content):esc(m.content)}</div>${live?`<div class="reply-progress" role="status"><span class="typing-dots" aria-hidden="true"><i></i><i></i><i></i></span><span>${esc(m.progress||'正在等模型回复…')}</span></div>`:''}${m.role==='assistant'&&!live&&m.usage?usageReceipt(m):''}${m.attachments?.length?`<div class="sent-attachments">${m.attachments.map(a=>`<span>附件 · ${esc(a.name)}</span>`).join('')}<small>本轮已附上；以后需要重读原件时，请再附一次。</small></div>`:''}${m.error?`<div class="retry-bar"><span>${esc(m.failure||'回答未完成')}</span>${retryRequest&&index===ensureSession().messages.length-1?'<button class="secondary" data-action="retry-chat">重试这条消息</button><button class="text-link" data-action="edit-retry">修改后再发</button>':''}</div>`:!live?experience.replyTools(m,index):''}</div>`;
}

function paintReply(s,m){if(queuedPaint.has(m))return;queuedPaint.add(m);setTimeout(()=>{queuedPaint.delete(m);if(!chatPage()||activeSession!==s)return;const box=$('#messages');if(!box)return;const bottom=box.scrollHeight-box.scrollTop-box.clientHeight<110,index=s.messages.indexOf(m),el=$(`[data-message-index="${index}"]`);if(el)el.outerHTML=messageView(m,index);if(bottom)box.scrollTop=box.scrollHeight;},40);}
function scrollChat(){setTimeout(()=>{const el=$('#messages');if(el)el.scrollTop=el.scrollHeight;},20);}
function demoReply(input){if(/词根|单词|表格/.test(input))return '可以。这里用 predict 做一个预设示例：\n\n| 单词 | 拆解线索 | 语境 |\n| --- | --- | --- |\n| predict | pre-（提前）+ dict（说） | predict the weather |\n\n先遮住释义：如果一个人 predicts the result，他是在结果出现之前，还是之后说出判断？\n\n你回答后，再用一个新语境检查是否记住。词根适合作为线索，并不是每个词都能这样拆。\n\n这个流程顺手的话，完成学习块时可以选择保留“词根＋语境＋表格”的偏好。';if(/复盘|六级|阅读|证据/.test(input))return '先把题目、相关原文和你的选择放在一起。\n\n① 你认为原文哪一句支持这个选项？\n② 另一个看似合理的选项，多加了什么条件？\n③ 换个表述，你还能识别同一个逻辑吗？\n\n这是证据链复盘的预设流程。没有实际原文时，不会编造答案或声称知道出题者意图。真实材料分析需要切换已授权接口。';if(/项目|团队|里程碑|有效/.test(input))return '我们可以先把“做一个学习工具”拆成三份可检查的成果：\n\n1. 问题说明：访谈记录里，用户在哪一步卡住？\n2. 可交互原型：从选策略到确认记忆，能否走通？\n3. 验证记录：同样学习时间下，迁移题和延迟回忆是否改善？\n\n先写一句话：你们第一周要交付的作品是什么，谁来验收？项目协作页可以记录负责人和任务状态。\n\n以上是预设项目引导，未自动创建远程协作空间。';if(/路线|计划|一周/.test(input))return `先按你目前的设置：每次 ${state.profile.minutes} 分钟。\n\n前 ${Math.min(5,Math.floor(state.profile.minutes/4))} 分钟：不看资料，试着解释上次学到的内容。\n中间 ${state.profile.minutes-2*Math.min(5,Math.floor(state.profile.minutes/4))} 分钟：只推进一个新知识点。\n最后 ${Math.min(5,Math.floor(state.profile.minutes/4))} 分钟：用一个新问题检查理解，并记下下次的起点。\n\n这是一份可调整的预设路线。今天最想解决的那个问题是什么？`;if(/简洁|直接|鼓励|风格/.test(input))return '收到。你可以在“学习偏好”里选择简洁直接、温和耐心或追问启发。\n\n演示回复是预先编写的，不能代表模型已经改变了表达方式；真实接口会收到你当前的风格策略。记忆与鼓励偏好也由你控制。';if(/回忆|练习/.test(input))return '做一个不看资料的小练习：\n\n如果用一句话解释“主动回忆”，你会怎样向同学说明它与反复阅读的区别？\n\n先自己回答，再核对：关键是尝试从记忆中提取信息，然后获得反馈。答错时先补足理解，缩短间隔再测；稳定成功后再延长。\n\n这段为预设练习，不对你的回答自动评分。';return '先试着用自己的话解释一下：你现在已经理解了什么，又卡在哪一个地方？\n\n我们可以按“先解释 → 找到一个缺口 → 换个例子再试”的顺序来。只解决眼前这一步。\n\n当前是预设对话演示，不会对你刚才的答案作出真实判断。连接已授权的本地接口后，才能根据具体内容继续分析。';}
async function requestChat(payload,signal,onUpdate){
 const options={method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal};
 let response=await window.learnflowFetch('/api/chat/stream',options);
 if(response.status===404){response=await window.learnflowFetch('/api/chat',options);let d;try{d=await response.json();}catch{throw Error('连接助手没有返回可读的回答，请检查连接。');}if(!response.ok)throw Error(d.message||'模型请求失败');return d;}
 if(!response.ok){let d;try{d=await response.json();}catch{}throw Error(d?.message||'模型请求失败，请检查连接。');}
 const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',result=null;
 const consume=line=>{if(!line.trim())return;const event=JSON.parse(line);if(event.type==='error')throw Error(event.message||'回答中断');if(event.type==='result')result=event;else onUpdate(event);};
 try{while(true){const part=await reader.read();if(part.done)break;buffer+=decoder.decode(part.value,{stream:true});let n;while((n=buffer.indexOf('\n'))>=0){consume(buffer.slice(0,n));buffer=buffer.slice(n+1);}}buffer+=decoder.decode();if(buffer.trim())consume(buffer);}finally{reader.releaseLock();}
 if(!result)throw Error('连接中断了，已收到的内容留在这里。');return result;
}
async function sendChat(content,retrying=false){
 const composer=window.LearnFlowComposer,attachments=retrying&&retryRequest?[...retryRequest.attachments]:[...(composer?.files()||[])];
 if(busy||composer?.ready()===false||(!String(content).trim()&&!attachments.length))return;
 if(attachments.length&&mode!=='api'){toast('先连接学习助手，才能读取这些附件。');window.LearnFlowConnection?.open();return;}
 const originalContent=content;content=String(content).trim()||(attachments.length?'请帮我理解这些学习资料。':'');
 if(mode==='api'&&!(await window.LearnFlowConnection?.health())?.configured){window.LearnFlowConnection?.open();return;}
 if(busy)return;
 const s=ensureSession(),participating=activeCards(s.scene).slice(0,12),requestMode=mode;
 if(retrying&&retryRequest?.session===s){if(s.messages.at(-1)?.error)s.messages.pop();}else{s.messages.push({role:'user',content,attachments:attachments.map(({name,kind,note})=>({name,kind,note}))});}
 retryRequest=null;sessionDrafts.delete(String(s.id));composer?.clear();busy=true;
 const m={role:'assistant',content:'',streaming:true,progress:attachments.length?'正在发送你选的资料…':'正在等模型回复…',source:requestMode==='api'?'授权接口':'预设演示 · 非模型生成',model:composer?.model()};s.messages.push(m);
 chatScroll=null;const controller=new AbortController();activeRequest={controller,session:s,message:m};render();
 try{
   if(requestMode==='api'){
     const data=await requestChat({attachments,model:composer?.model(),messages:s.messages.filter(x=>!x.error&&!x.streaming&&(x.role==='user'||x.source?.startsWith('授权接口'))).slice(-40).map(({role,content})=>({role,content})),memories:state.profile.memory?state.memories.filter(x=>x.sceneId===s.scene).slice(-20).map(({id,title,content})=>({id,title,content})):[],strategies:participating.map(c=>({id:c.id,title:c.title,instructions:c.instructions})),preferences:state.profile,scene:s.scene},controller.signal,event=>{
       if(event.type==='delta'&&typeof event.text==='string'){m.content+=event.text;m.progress='正在回答…';paintReply(s,m);}
       if(event.type==='status'){m.progress=event.message||'正在准备回答…';paintReply(s,m);}
     });
     if(typeof data.reply!=='string'||!data.reply.trim())throw Error('模型返回了空内容，请重试或换一个模型。');
     Object.assign(m,{content:data.reply,status:data.status,learning:data.learning,source:'授权接口',model:data.model||composer?.model(),usage:{actual:data.usage?.source==='provider'&&Number.isFinite(data.usage.total_tokens)?data.usage.total_tokens:null,estimated:null,source:data.usage?.source||'unavailable'},providerUsage:data.usage,billing:data.billing,receipt:data.receipt,clientName:data.client?.name,streaming:false});composer?.success(m.model);
     if(Number.isFinite(data.usage?.total_tokens))recordUsage(data.usage.total_tokens,'actual',participating);
   }else{const reply=demoReply(content);const estimate=Math.ceil((content.length+reply.length)/1.5);Object.assign(m,{content:reply,streaming:false,usage:{actual:null,estimated:estimate,source:'estimated'}});recordUsage(estimate,'estimated',participating);}
 }catch(e){
   const stopped=controller.signal.aborted;m.content=window.LearnFlowText.visibleStream(m.content);Object.assign(m,{streaming:false,error:true,stopped,failure:stopped?'已停止生成，草稿和附件还在。':e.message});
   if(!composer?.draft?.()?.trim())composer?.restore(attachments,originalContent);if(!stopped)composer?.failure(e.message);
   retryRequest={session:s,content:originalContent,attachments};toast(stopped?'已停止。可以修改问题，也可以重试。':'回答没完成，草稿和附件已保留。');
 }finally{busy=false;activeRequest=null;persistSession(s);if(chatPage())render();else renderHistory();}
}
function stopChat(){activeRequest?.controller.abort();}
function recordUsage(amount,type,participating=activeCards()){amount=Math.max(0,Math.round(amount));if(!participating.length)return;const base=Math.floor(amount/participating.length),extra=amount%participating.length;participating.forEach((c,i)=>{const u=state.usage[c.id]||{actual:0,estimated:0};u[type]+=base+(i<extra?1:0);state.usage[c.id]=u;});save();}
function persistSession(s=ensureSession()){sessionPool.set(s.id,s);if(!state.profile.memory)return;const i=state.sessions.findIndex(x=>x.id===s.id);if(i<0)state.sessions.push(structuredClone(s));else state.sessions[i]=structuredClone(s);save();}
function memoryView(){return head('学习记忆','你确认的偏好，才会成为记忆。每一条都能修改、删除或带走。',`<button class="secondary" data-action="export-memory">导出记忆</button>`)+`<div class="ui-toolbar"><span>学习记忆：${state.profile.memory?'已开启':'已关闭'}</span><a href="#settings/general">设置</a></div>${state.memories.length?state.memories.map(m=>`<article class="memory-card"><div class="memory-meta"><span>由你确认 · ${new Date(m.created).toLocaleDateString('zh-CN')}</span><span>${esc(m.scene)}</span></div><h3>${esc(m.title)}</h3><p>${esc(m.content)}</p><div class="tags">${m.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="button-row" style="margin-top:18px"><button class="primary" data-memory-card="${esc(m.id)}">提炼成专属策略</button><button class="secondary" data-memory-edit="${esc(m.id)}">编辑</button><button class="text-link" data-memory-delete="${esc(m.id)}">删除记忆</button></div></article>`).join(''):'<div class="empty">暂无学习记忆</div>'}`;}
function showMemoryForm(existing){const text=activeSession?.messages.map(m=>m.content).join(' ')||'';const roots=/词根|单词/.test(text);showModal(modalHead(existing?'修改这条学习记忆':'这一段学习，要留下些什么？')+`<p class="modal-copy">${existing?'修改后将替换本机这条记忆。':'下面是根据关键词准备的候选偏好。请核对、修改；确认后才会保存。'}</p><form id="memory-form" data-id="${esc(existing?.id||'')}"><label class="field">记忆标题<input name="title" required maxlength="60" value="${esc(existing?.title||(roots?'用词根、语境和表格学词汇':'先自己解释，再检查理解'))}"></label><label class="field">我想保留的偏好<textarea name="content" required maxlength="2000">${esc(existing?.content||(roots?'学习词汇时，我希望先看可靠的词根线索，再看真实语境，最后做主动回忆。':'学习新概念时，先让我用自己的话解释，每轮只指出一个理解缺口，再换个例子检查。'))}</textarea></label><div class="form-grid"><label class="field">输出形式<select name="format"><option>紧凑表格</option><option>简洁分点</option><option>自然段落</option><option>思维导图提纲</option></select></label><label class="field">引导方式<select name="guidance"><option>先让我尝试</option><option>先给一个示例</option><option>直接讲清楚</option></select></label></div>${!state.profile.memory?'<label class="switch-row"><span><strong>开启本机学习记忆</strong><p>允许保存学习记录与本条偏好，可随时关闭。</p></span><input class="toggle" type="checkbox" name="consent" required aria-label="同意开启本机记忆"></label>':''}<div class="button-row" style="margin-top:22px"><button class="primary" type="submit">确认并保存记忆</button><button class="secondary" type="button" data-action="close">这次不保存</button></div></form>`);if(existing){$('[name="format"]',$('#memory-form')).value=existing.format||existing.tags?.[0]||'紧凑表格';$('[name="guidance"]',$('#memory-form')).value=existing.guidance||existing.tags?.[1]||'先让我尝试';}}
function showCreateCard(prefill={}){window.LearnFlowCardStudio.open({showModal,modalHead,esc,icon,prefill});}
function detail(id){const c=cardBy(id);if(!c)return;const u=state.usage[id]||{};showModal(modalHead(c.title)+`<div class="tags">${c.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>${window.LearnFlowStrategyGuide.view(c,{esc,icon})}<div class="info-strip">我的评分 · 使用权重 ${Math.min(1,Math.log1p(u.actual||0)/Math.log(10001)).toFixed(2)}<br>权重只根据真实接口分摊量计算；演示用量不增加权重。</div><div class="rating" aria-label="给策略评分">${[1,2,3,4,5].map(n=>`<button data-rating="${esc(id)}" data-value="${n}" class="${n<=(state.ratings[id]||0)?'on':''}" aria-label="评分 ${n} 星">★</button>`).join('')}</div><div class="button-row"><button class="primary" data-adopt="${esc(id)}">${state.adopted.includes(id)?'停用这张策略':'采纳并启用'}</button><button class="secondary" data-export-card="${esc(id)}">导出 JSON</button><button class="secondary" data-export-skill="${esc(id)}">导出 SKILL.md</button>${c.id.startsWith('custom-')?`<button class="secondary" data-edit-card="${esc(id)}">编辑卡片</button><button class="secondary danger" data-delete-card="${esc(id)}">删除</button>`:''}</div><p class="source-label">${esc(c.source||'本机个人策略')}</p>`);}
function projectView(){return head('任务看板','任务分给谁，做到哪一步了，在这里记下来。',`<button class="primary" data-action="add-task">＋ 新建任务</button>`)+`<div class="ui-toolbar"><button class="secondary" data-action="export-project">导出任务</button><button class="secondary" data-action="import-project">导入任务</button><details class="ui-help"><summary>协作说明</summary><p>任务保存在本机。可导出文件交给队友导入，暂不支持实时同步。</p></details></div><div class="section-heading"><h2>项目进展</h2><button class="text-link" data-action="project-template">使用模板</button></div><div class="kanban">${[['todo','待开始'],['doing','进行中'],['done','已完成']].map(([id,title])=>`<section class="kanban-column"><h3>${title} · ${state.tasks.filter(t=>t.status===id).length}</h3>${state.tasks.filter(t=>t.status===id).map(t=>`<article class="task"><p>${esc(t.title)}</p><small>${esc(t.owner||'待分工')} · ${esc(t.evidence||'待补充验收依据')}</small><select data-task="${esc(t.id)}" aria-label="${esc(t.title)}的状态">${[['todo','待开始'],['doing','进行中'],['done','已完成']].map(([v,l])=>`<option value="${v}" ${t.status===v?'selected':''}>${l}</option>`).join('')}</select><button class="text-link" data-delete-task="${esc(t.id)}">删除任务</button></article>`).join('')||'<p class="mini-note">暂无任务</p>'}</section>`).join('')}</div>`;}
function teacherView(){return head('教师伙伴 · 让反馈有依据','把学习过程整理清楚，把最终判断交给教师。')+`<div class="two-col"><section class="setting-card"><h2>选择愿意分享的证据</h2><p class="modal-copy">本页只生成本机草稿，点击导出后由你自行分享。不会自动发给教师。</p><form id="teacher-form"><label class="field">学习目标<input name="goal" required value="${esc(state.profile.goal)}" placeholder="例如：能依据原文排除阅读干扰项"></label><label class="field">本次学习产出与证据<textarea name="evidence" required placeholder="填写一段解释、一次变式题作答、作品链接或项目完成依据"></textarea></label><label class="field">仍然遇到的困难<textarea name="difficulty" placeholder="希望老师帮忙核验什么？"></textarea></label><label class="switch-row"><strong>包含学习块数量与方法列表</strong><input type="checkbox" class="toggle" name="include" checked></label><button class="primary" type="submit" style="margin-top:20px">生成过程评价草稿</button></form></section><section class="setting-card"><h2>可以辅助什么</h2><ol class="compact-list"><li>对齐学习目标与可观察成果</li><li>整理学习者主动分享的过程证据</li><li>提示还需要核验的知识断点</li><li>给出下一轮教学设计的起点</li></ol><div class="info-strip">不会依据 Token 用量给能力打分。当前为模板整理；缺少原始作答、评分标准或教师核验时，不生成正式成绩。</div><button class="secondary" data-detail="teacher">查看教师辅助策略</button></section></div><div id="teacher-output"></div>`;}
function connectorsView(){return head('连接器','连接你已经在用的工具。读取资料或发消息前，都会让你确认。',`<button class="secondary" data-action="check-api">学习助手设置</button>`)+`<div class="connector-grid">${[{name:'本机学习助手',icon:'spark',text:'使用 WorkBuddy 附带的 CodeBuddy 入口。确认后才能发送对话和附件，网页会显示连接结果。',status:'可连接',action:'check-api'},{name:'课件与资料',icon:'clipboard',text:'在对话框里拖入 PDF、图片或文字文件即可。会议记录可手动导出后使用；不会自动读取腾讯会议。',status:'选文件后读取',action:'connector-info'},{name:'学习提醒',icon:'clock',text:'把一次学习安排加入常用日历。QQ 消息连接在下方单独设置。',status:'可导出日历',action:'calendar'},{name:'LearnFlow 宿主扩展',icon:'layers',text:'交付包中的 Skill 与 MCP 工具可以装进支持的宿主，查询策略、整理学习块和保存资料。',status:'查看安装说明',action:'mcp-info'}].map(c=>`<article class="connector"><div class="connector-head"><span class="symbol orange">${icon(c.icon)}</span><span class="status-pill">${c.status}</span></div><h3>${c.name}</h3><p>${c.text}</p><button class="secondary" data-action="${c.action}">${c.action==='calendar'?'下载学习提醒':c.action==='check-api'?'连接设置':'查看说明'} ↗</button></article>`).join('')}</div>${window.LearnFlowEcosystem?.view()||''}`;}
function settingsView(){return head('按你的方式学习','引导多一点，还是安静一点，都由你说了算。')+`<form id="settings-form"><section class="setting-card"><h2>学习偏好</h2><div class="form-grid"><label class="field">当前学习目标<input name="goal" maxlength="200" value="${esc(state.profile.goal)}" placeholder="例如：独立完成六级阅读复盘"></label><label class="field">一次可以投入的时间<select name="minutes">${[10,15,25,45,60].map(n=>`<option value="${n}" ${state.profile.minutes===n?'selected':''}>${n} 分钟</option>`).join('')}</select></label><label class="field">希望怎样引导<select name="guide">${[['gentle','轻引导：需要时给下一步'],['strong','强引导：步骤更明确'],['free','自主探索：由我决定节奏']].map(([v,t])=>`<option value="${v}" ${state.profile.guide===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">希望怎样交流<select name="style">${[['plain','简洁直接'],['warm','温和耐心'],['socratic','追问启发']].map(([v,t])=>`<option value="${v}" ${state.profile.style===v?'selected':''}>${t}</option>`).join('')}</select></label></div><label class="field">鼓励偏好<select name="encourage">${[['quiet','安静陪伴，不主动鼓励'],['timely','困难时，具体而克制地鼓励'],['strong','希望获得更主动的支持']].map(([v,t])=>`<option value="${v}" ${state.profile.encourage===v?'selected':''}>${t}</option>`).join('')}</select></label></section><section class="setting-card"><h2>学习记忆</h2><label class="switch-row"><span><strong>开启学习记忆</strong><p>将对话记录保存在本机；新增偏好依然需要你确认。关闭后不再写入对话记忆。</p></span><input name="memory" type="checkbox" class="toggle" ${state.profile.memory?'checked':''}></label><div class="button-row"><button class="secondary" type="button" data-action="export-all">导出全部本机数据</button><button class="secondary" type="button" data-action="restore-backup">恢复本机备份</button><button class="secondary danger" type="button" data-action="clear-data">清除本机数据</button></div></section><button class="primary" type="submit">保存我的偏好</button></form>`;}
function aboutView(){return head('LearnFlow学习流动','基于可进化学习策略与腾讯 Buddy 生态的自主学习支持平台。')+`<div class="setting-card about-copy"><h2>让方法被真正用起来</h2><p>我们围绕自主学习者，建立“选择策略 → 学习执行 → 过程证据 → 确认记忆 → 个人策略”的闭环。应试、自学和项目式学习共用一套可迁移的方法层。</p><h3>当前可体验</h3><p>本地策略检索、收藏、个人评分、启停、导入导出；三种学习场景；预设演示与授权接口入口；记忆确认和个人策略；项目任务看板；教师评价草稿；学习偏好与数据控制。</p><h3>当前边界</h3><p>本页是参赛团队独立原型，不是腾讯官方发布界面。预设聊天不是模型调用。云端社区、QQ / 微信主动消息、会议解析、实时协作与腾讯应用审核均未在此静态版本完成。</p><h3>Skill 与 MCP 各司其职</h3><p>策略描述何时、如何学习；MCP 提供标准化工具调用。两者互补，使用 MCP 本身并不保证策略能抵抗所有模型变化。需要版本管理、测试集与兼容性回测。</p><h3>参考与部署</h3><ul><li><a href="https://open.workbuddy.cn/docs/buddy-app" target="_blank" rel="noopener">腾讯 Buddy 应用官方说明</a></li><li><a href="https://github.com/banddidonunomarisa741-hub/cet6-intellect-crush-review-skill" target="_blank" rel="noopener">团队 CET-6 开源策略参考</a></li><li><a href="https://github.com/new" target="_blank" rel="noopener">路线 A：创建 GitHub 仓库并启用 Pages</a></li><li><a href="https://app.netlify.com/drop" target="_blank" rel="noopener">路线 B：将静态网站文件夹拖入 Netlify Drop</a></li></ul><p>项目源码按随包 LICENSE 开源。当前标识采用团队提供的 F 形 Logo，已替换此前的猫咪参考素材；本项目为独立学生团队项目。</p></div>`;}
function onboarding(){experience.onboarding();}
function exportSkill(c){const name=c.id.replace(/[^a-z0-9-]/g,'-');return `---\nname: ${name}\ndescription: ${JSON.stringify(c.description)}\n---\n\n# ${c.title}\n\n## 使用场景\n${c.category||c.scene}\n\n## 执行步骤\n${c.instructions}\n\n## 学习者控制\n记忆需确认，风格可调整；不以 Token 用量判定掌握。\n\n## 验证\n请用独立作答、迁移题或延迟回忆核验效果。\n`;}
function exportAll(){download('learnflow-local-backup.json',JSON.stringify({...state,workspace:workspaceSidebar.exportData()},null,2),'application/json');toast('已导出本机数据和项目分组；分享前请检查其中的个人学习记录。');}
function calendar(){const start=new Date(Date.now()+30*60000),end=new Date(start.getTime()+state.profile.minutes*60000),stamp=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');download('learnflow-study.ics',`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//LearnFlow//Study//ZH\r\nBEGIN:VEVENT\r\nUID:${Date.now()}@learnflow.local\r\nDTSTAMP:${stamp(new Date())}\r\nDTSTART:${stamp(start)}\r\nDTEND:${stamp(end)}\r\nSUMMARY:学习流动 - 完成一个学习块\r\nDESCRIPTION:选择一张策略卡\, 按自己的节奏开始。\r\nBEGIN:VALARM\r\nTRIGGER:-PT5M\r\nACTION:DISPLAY\r\nDESCRIPTION:给学习留一点时间\r\nEND:VALARM\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n`,'text/calendar;charset=utf-8');toast('已生成 30 分钟后的日历事件，导入日历后由日历应用提醒。');}
async function checkAPI(){if(window.LearnFlowConnection)return window.LearnFlowConnection.open();apiStatus='正在检测本机服务…';render();try{const r=await fetch('/api/health');const d=await r.json();apiStatus=JSON.stringify(d);}catch{apiStatus='未发现本地接口。双击网页或静态托管仅支持本地演示；请运行启动脚本后再检测。';}render();}
function startSession(scene,prompt){if(busy){toast('当前回复还在处理中，完成后再开始新学习。');return}stashDraft();window.LearnFlowComposer?.reset();retryRequest=null;if(activeSession?.messages.length)persistSession(activeSession);chatScroll=null;state.scene=scene;activeSession={id:Date.now(),scene,messages:[],completed:false,created:new Date().toISOString()};save();navigate('home');if(prompt)setTimeout(()=>sendChat(prompt),0);}
const actions={
'remember-learning':()=>showMemoryForm(),'search-chats':searchChats,'learning-options':learningOptions,'chat-options':chatOptions,
'browse-methods':()=>{$('#modal').close();navigate('market');},
'open-settings':()=>{$('#modal').close();navigate('settings/general');},
'study-time':()=>showModal(modalHead('这次留多少时间？')+`<p class="modal-copy">下一次回答会参考这个时长来安排内容。</p><div class="time-choices">${[10,15,25,45,60].map(n=>`<button data-study-minutes="${n}" aria-pressed="${state.profile.minutes===n}" class="${state.profile.minutes===n?'selected':''}">${n}<small>分钟</small></button>`).join('')}</div>`),
'profile-menu':()=>{const menu=$('#profile-menu');menu.innerHTML=`<div class="profile-menu-heading">我的学习空间</div><a href="#settings/general">${icon('settings')}设置<span>Ctrl ,</span></a><a href="#settings/memory">${icon('heart')}学习记忆</a><a href="#settings/connections">${icon('plug')}模型与连接</a><button data-action="help">${icon('compass')}使用指南</button>`;menu.hidden=!menu.hidden;$('.profile').setAttribute('aria-expanded',String(!menu.hidden));},
'rename-chat':()=>showModal(modalHead('给这段学习起个名字')+`<form id="rename-chat-form"><label class="field">对话名称<input name="title" maxlength="80" required value="${esc(sessionTitle(ensureSession()))}"></label><button class="primary" type="submit">保存</button></form>`),
'export-chat':()=>{const s=ensureSession();download('LearnFlow-'+sessionTitle(s).replace(/[<>:"/\\|?*]/g,'-')+'.md',s.messages.map(m=>`## ${m.role==='user'?'我':'LearnFlow'}\n\n${m.content}`).join('\n\n'));$('#modal').close();},

'stop-chat':stopChat,'retry-chat':()=>{if(retryRequest)sendChat(retryRequest.content,true);},'edit-retry':()=>{$('#chat-input')?.focus();},'toggle-chat-mode':()=>{if(busy)return;if(mode==='api'){mode='demo';render();toast('已切换为演示回复。');}else{window.LearnFlowConnection?.open();}},'close':()=>$('#modal').close(),'menu':()=>{if(innerWidth<=760){const open=$('.sidebar').classList.toggle('open');document.body.classList.toggle('nav-open',open);}else document.body.classList.toggle('sidebar-collapsed');},'new-session':()=>startSession(state.scene),'resume-session':()=>{activeSession=null;ensureSession();navigate('session');},'onboard':onboarding,'help':()=>showModal(modalHead('三步，开始你的学习流动')+'<ol class="detail-steps"><li>选场景，或直接说出学习目标。</li><li>挑 1–2 张策略卡，完成一个学习块。</li><li>确认有用的偏好，生成自己的策略。</li></ol><p class="modal-copy">先体验预设流程。真实模型需要本地服务和显式授权；所有连接状态都能在“连接器”查看。</p><button class="primary" data-action="onboard">设置我的学习起点</button>'),
'restore-backup':restoreBackup,'create-card':()=>showCreateCard(),'complete-block':()=>{if(busy)return toast('先等这条回答完成，再整理学习块。');const s=ensureSession();const index=s.messages.findLastIndex(m=>m.role==='assistant'&&!m.error&&!m.streaming);if(index<0)return toast('先完成一段对话，再整理学习块。');experience.saveDialog(index,true);},'export-all':exportAll,'export-memory':()=>download('learnflow-memories.json',JSON.stringify(state.memories,null,2),'application/json'),'export-strategies':()=>download('learnflow-strategies.json',JSON.stringify(cards().filter(c=>state.adopted.includes(c.id)),null,2),'application/json'),'export-project':()=>download('learnflow-project.json',JSON.stringify({version:1,tasks:state.tasks},null,2),'application/json'),'import-card':()=>importJSON('card'),'import-project':()=>importJSON('project'),'check-api':checkAPI,'calendar':calendar,
 'api-info':()=>window.LearnFlowConnection?.open(),
 'connector-info':()=>showModal(modalHead('把资料带进对话')+'<p class="modal-copy">拖入 PDF、图片、TXT 或 Markdown 等文字文件，检查附件后点击发送。PDF 读取文字，扫描版请使用截图；Word 和 PPT 可先导出 PDF。</p><p class="modal-copy">腾讯会议记录需要你自行导出，再选择文件。LearnFlow 不会自动读取会议或其他本机文件。</p><button class="primary" data-action="close">知道了</button>'),
 'mcp-info':()=>showModal(modalHead('在 LearnBuddy 里使用 LearnFlow')+'<p class="modal-copy">宿主扩展包包含学习策略和本地工具。安装后，通过宿主的专家、技能与连接器入口使用；宿主的侧栏和模型选择由原客户端管理。</p><p class="modal-copy">MCP 是助手调用工具的通用方式。学习资料和个人策略的保存仍需要你的确认。</p><a class="secondary" href="https://github.com/banddidonunomarisa741-hub/learnflow-buddy/tree/main/buddy-app" target="_blank" rel="noopener">查看扩展包与安装说明</a>'),
'clear-data':()=>showModal(modalHead('清除本机学习数据')+'<p class="modal-copy">将删除此浏览器里学习流动保存的策略、收藏、评分、记忆、任务和项目分组。可以先导出备份。</p><div class="button-row"><button class="secondary" data-action="export-all">先导出备份</button><button class="primary" data-action="confirm-clear">确认清除本机数据</button></div>'),
'confirm-clear':()=>{if(busy){toast('请等待当前接口返回后再清除数据。');return}if(workspaceSidebar.clearData()===false)return;state=initial();activeSession=null;sessionPool.clear();sessionDrafts.clear();window.LearnFlowComposer?.reset();save();settingsUI.applyAppearance();$('#modal').close();render();toast('本机学习流动数据和项目分组已清除。');},
'add-task':()=>showModal(modalHead('新建任务')+'<form id="task-form"><label class="field">任务名称<input name="title" required maxlength="160"></label><label class="field">负责人<input name="owner" maxlength="60" placeholder="例如：前端小组"></label><label class="field">完成标准<input name="evidence" required maxlength="200" placeholder="例如：能走通策略选择到记忆保存"></label><button class="primary" type="submit">添加任务</button></form>'),
'project-template':()=>{if(state.tasks.length){toast('已有项目任务，可直接添加新任务。');return}state.tasks=[{id:'t1',title:'明确学习者的一个实际困难',owner:'产品小组',evidence:'问题记录与原始访谈证据',status:'todo'},{id:'t2',title:'走通策略卡到学习记忆的原型',owner:'前端小组',evidence:'可交互演示与验证记录',status:'todo'},{id:'t3',title:'设计一次可复核的学习验证',owner:'评估小组',evidence:'同时间迁移题与延迟测验方案',status:'todo'}];save();render();toast('已添加项目模板，负责人和完成依据供你调整。');}
};
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;const d=el.dataset;if(d.action&&actions[d.action]){e.preventDefault();actions[d.action]();}else if(d.session)openSession(d.session);else if(d.currentScene){if(busy)return toast('先等当前回答完成，再调整学习场景。');state.scene=d.currentScene;ensureSession().scene=d.currentScene;save();const wasOpen=$('#modal').open;render();if(wasOpen)learningOptions();}else if(d.studyMinutes){state.profile.minutes=Number(d.studyMinutes);save();$('#modal').close();render();}else if(d.nav)navigate(d.nav);else if(d.scene)startSession(d.scene);else if(d.prompt)sendChat(d.prompt);else if(d.filter){filter=d.filter;render();}else if(d.detail)detail(d.detail);else if(d.favorite){state.favorites=state.favorites.includes(d.favorite)?state.favorites.filter(x=>x!==d.favorite):[...state.favorites,d.favorite];save();render();}else if(d.adopt){const exists=state.adopted.includes(d.adopt);state.adopted=exists?state.adopted.filter(x=>x!==d.adopt):[...state.adopted,d.adopt];save();if($('#modal').open)detail(d.adopt);render();toast(exists?'已停用':'已启用');}else if(d.rating){state.ratings[d.rating]=Number(d.value);save();detail(d.rating);render();}else if(d.exportCard)download(`${d.exportCard}.json`,JSON.stringify(cardBy(d.exportCard),null,2),'application/json');else if(d.exportSkill)download('SKILL.md',exportSkill(cardBy(d.exportSkill)));else if(d.memoryCard){const m=state.memories.find(x=>x.id===d.memoryCard);showCreateCard({title:m.title,description:'从我确认的学习偏好提炼。',instructions:m.content,tags:m.tags,scene:m.sceneId});}else if(d.memoryEdit)showMemoryForm(state.memories.find(x=>x.id===d.memoryEdit));else if(d.memoryDelete){state.memories=state.memories.filter(x=>x.id!==d.memoryDelete);save();render();toast('记忆已删除；由其生成的策略可在我的策略中单独管理。');}else if(d.copyCard){const c=cardBy(d.copyCard);if(c)showCreateCard({...c,id:undefined,title:(c.title+' · 我的版本').slice(0,60)});}else if(d.editCard){showCreateCard(cardBy(d.editCard));}else if(d.deleteCard){state.custom=state.custom.filter(c=>c.id!==d.deleteCard);state.adopted=state.adopted.filter(x=>x!==d.deleteCard);state.favorites=state.favorites.filter(x=>x!==d.deleteCard);delete state.ratings[d.deleteCard];delete state.usage[d.deleteCard];save();$('#modal').close();render();}else if(d.deleteTask){state.tasks=state.tasks.filter(t=>t.id!==d.deleteTask);save();render();}});
document.addEventListener('input',e=>{if(e.target.id==='strategy-search'){query=e.target.value;gallery.update(marketCards());}});
window.addEventListener('learnflow-connected',()=>{mode='api';if(chatPage())render();});
window.addEventListener('learnflow-disconnected',()=>{mode='demo';if(chatPage())render();});
document.addEventListener('change',e=>{if(e.target.dataset.methodToggle){const id=e.target.dataset.methodToggle;state.adopted=e.target.checked?[...new Set([...state.adopted,id])]:state.adopted.filter(x=>x!==id);save();render();return;}if(e.target.id==='chat-mode'){mode=e.target.value;if(mode==='api')window.LearnFlowConnection?.open();toast(mode==='api'?'将使用已授权本地接口，失败会明确显示。':'已切回预设演示，无模型调用。');}if(e.target.dataset.task){const t=state.tasks.find(t=>t.id===e.target.dataset.task);if(t){t.status=e.target.value;save();render();}}});
document.addEventListener('submit',e=>{const form=e.target;if(!['home-prompt','chat-form','memory-form','card-form','settings-form','guide-form','task-form','teacher-form'].includes(form.id))return;e.preventDefault();const f=new FormData(form),v=Object.fromEntries(f.entries());if(form.id==='home-prompt'){const val=$('#home-input').value.trim();if(val)startSession(state.scene,val);else startSession(state.scene);}else if(form.id==='chat-form'){sendChat($('#chat-input').value);}else if(form.id==='memory-form'){if(!state.profile.memory&&!f.has('consent'))return;state.profile.memory=true;const existing=state.memories.find(m=>m.id===form.dataset.id);const record={id:existing?.id||'memory-'+Date.now(),title:v.title.trim(),content:v.content.trim().replace(/\n输出偏好：[^\n]*。引导：[^\n]*。$/u,'')+`\n输出偏好：${v.format}。引导：${v.guidance}。`,format:v.format,guidance:v.guidance,tags:[v.format,v.guidance],scene:existing?.scene||LF_SCENES[state.scene].title,sceneId:existing?.sceneId||state.scene,created:existing?.created||new Date().toISOString()};if(existing)state.memories[state.memories.indexOf(existing)]=record;else state.memories.push(record);persistSession();save();$('#modal').close();navigate('memory');toast('已按你的确认保存，可随时修改或删除。');}else if(form.id==='card-form'){if(!v.title.trim()||!v.description.trim()||!v.instructions.trim())return toast('请写下名称、介绍和具体做法。');const existing=state.custom.find(c=>c.id===form.dataset.id);const c={id:existing?.id||'custom-'+Date.now(),title:v.title.trim(),description:v.description.trim(),instructions:v.instructions.trim(),tags:v.tags.split(/[,，]/).map(t=>t.trim()).filter(Boolean).slice(0,6),scene:v.scene,category:LF_SCENES[v.scene]?.title||'交流风格',source:'我的专属策略',icon:'heart',color:['orange','green','blue','purple'].includes(v.color)?v.color:'orange',steps:v.instructions.trim().split(/\n+/).filter(Boolean).slice(0,3).map(s=>s.replace(/^\s*\d+[.、)）]\s*/,''))};if(existing)state.custom[state.custom.indexOf(existing)]=c;else state.custom.push(c);if(!state.adopted.includes(c.id))state.adopted.push(c.id);save();$('#modal').close();gallery.select(c.id);filter='all';query='';navigate('market');toast('专属策略已生成并启用。');}else if(form.id==='settings-form'){const memoryWasOn=state.profile.memory;state.profile={goal:v.goal.trim(),minutes:Number(v.minutes),guide:v.guide,style:v.style,encourage:v.encourage,memory:f.has('memory')};if(!memoryWasOn&&state.profile.memory&&activeSession?.messages.length)persistSession(activeSession);save();toast('偏好已保存');}else if(form.id==='guide-form'){guideDraft={...guideDraft,...v};if(guideStep===2){guideDraft.memory=f.has('memory');guideDraft.minutes=Number(guideDraft.minutes);state.profile=guideDraft;state.onboarded=true;save();$('#modal').close();render();toast('路线已准备好，从一个学习场景开始吧。');}else{guideStep++;drawGuide();}}else if(form.id==='task-form'){state.tasks.push({id:'task-'+Date.now(),title:v.title.trim(),owner:v.owner.trim(),evidence:v.evidence.trim(),status:'todo'});save();$('#modal').close();render();}else if(form.id==='teacher-form'){const report=`学习流动 · 过程评价草稿（待教师人工核验）\n\n学习目标\n${v.goal}\n\n学习者提交的证据（尚未独立核验）\n${v.evidence}\n\n自述困难\n${v.difficulty||'未填写'}\n\n${f.has('include')?`过程记录\n主动确认完成 ${state.blocks} 个学习块；启用方法：${cards().filter(c=>state.adopted.includes(c.id)).map(c=>c.title).join('、')}。\n\n`:''}教师核验建议\n1. 查看原始产出，检查目标与证据是否对应。\n2. 请学习者独立完成一道迁移问题。\n3. 根据实际作答安排下一轮教学，而非依据 Token 用量。\n\n状态：模板生成，未经教师核验，不是正式成绩。`;$('#teacher-output').innerHTML=`<div class="report">${esc(report)}</div><button class="secondary" id="export-report" style="margin-top:15px">导出这份草稿</button>`;$('#export-report').onclick=()=>download('learnflow-teacher-draft.md',report);}});
function restoreBackup(){
 const picker=document.createElement('input');picker.type='file';picker.accept='.json,application/json';
 picker.onchange=async()=>{const file=picker.files[0];if(!file)return;
  try{if(file.size>5000000)throw Error('备份超过 5 MB');const d=JSON.parse(await file.text());
   if(d.version!==1||!d.profile||!['custom','memories','sessions','tasks','adopted','favorites'].every(k=>Array.isArray(d[k])))throw Error('不是受支持的学习流动备份');
   const clean=initial(),str=(x,max=8000)=>String(x??'').slice(0,max),scene=x=>['exam','self','project'].includes(x)?x:'self';
   clean.profile={goal:str(d.profile.goal,200),minutes:[10,15,25,45,60].includes(d.profile.minutes)?d.profile.minutes:25,guide:['gentle','strong','free'].includes(d.profile.guide)?d.profile.guide:'gentle',style:['plain','warm','socratic'].includes(d.profile.style)?d.profile.style:'plain',encourage:['quiet','timely','strong'].includes(d.profile.encourage)?d.profile.encourage:'quiet',memory:d.profile.memory===true};
   clean.custom=d.custom.slice(0,200).map((c,i)=>{if(typeof c.id!=='string'||!/^custom-[a-z0-9-]{1,72}$/.test(c.id)||typeof c.instructions!=='string')throw Error('策略字段无效');return{id:str(c.id,80),title:str(c.title,60),description:str(c.description,160),instructions:str(c.instructions),scene:c.scene==='all'?'all':scene(c.scene),category:str(c.category,30),tags:Array.isArray(c.tags)?c.tags.slice(0,6).map(t=>str(t,30)):[],icon:'heart',color:['orange','green','blue','purple'].includes(c.color)?c.color:'orange',source:'恢复的个人策略'};});
   const ids=new Set([...LF_CARDS,...clean.custom].map(c=>c.id));clean.adopted=[...new Set(d.adopted.filter(id=>ids.has(id)))];clean.favorites=[...new Set(d.favorites.filter(id=>ids.has(id)))];
   for(const id of ids){const r=d.ratings?.[id];if(Number.isInteger(r)&&r>=1&&r<=5)clean.ratings[id]=r;const u=d.usage?.[id];if(u)clean.usage[id]={actual:Number.isFinite(u.actual)&&u.actual>=0?Math.floor(u.actual):0,estimated:Number.isFinite(u.estimated)&&u.estimated>=0?Math.floor(u.estimated):0};}
   clean.memories=d.memories.slice(0,500).map((m,i)=>({id:str(m.id||'memory-'+Date.now()+'-'+i,80),title:str(m.title,60),content:str(m.content,2500),format:str(m.format||m.tags?.[0],60),guidance:str(m.guidance||m.tags?.[1],60),tags:Array.isArray(m.tags)?m.tags.slice(0,6).map(t=>str(t,30)):[],sceneId:scene(m.sceneId),scene:LF_SCENES[scene(m.sceneId)].title,created:!isNaN(Date.parse(m.created))?m.created:new Date().toISOString()}));
   clean.sessions=d.sessions.slice(-100).map((s,i)=>({id:Number(s.id)||Date.now()+i,title:str(s.title,80),scene:scene(s.scene),created:str(s.created,80),completed:s.completed===true,messages:Array.isArray(s.messages)?s.messages.slice(-200).filter(m=>['user','assistant'].includes(m.role)&&typeof m.content==='string').map(m=>({role:m.role,content:str(m.content,24000),source:str(m.source,100),error:m.error===true,model:str(m.model,200),usage:m.usage?{actual:Number.isFinite(m.usage.actual)&&m.usage.actual>=0?m.usage.actual:null,estimated:Number.isFinite(m.usage.estimated)&&m.usage.estimated>=0?m.usage.estimated:null,source:'restored'}:undefined})):[]}));
   clean.ui={theme:['light','dark','system'].includes(d.ui?.theme)?d.ui.theme:'system',textSize:['compact','normal','large'].includes(d.ui?.textSize)?d.ui.textSize:'normal',reducedMotion:d.ui?.reducedMotion===true};
   clean.tasks=d.tasks.slice(0,500).map((t,i)=>({id:str(t.id||'task-'+i,80),title:str(t.title,160),owner:str(t.owner,60),evidence:str(t.evidence,200),status:['todo','doing','done'].includes(t.status)?t.status:'todo'}));clean.blocks=Number.isInteger(d.blocks)&&d.blocks>=0?d.blocks:0;clean.scene=scene(d.scene);clean.onboarded=d.onboarded===true;
   const workspace=workspaceSidebar.validateData(d.workspace);
   showModal(modalHead('确认恢复这份备份')+`<p class="modal-copy">将恢复 ${clean.custom.length} 张个人策略、${clean.memories.length} 条记忆、${clean.tasks.length} 个任务、${clean.sessions.length} 段对话和 ${workspace.projects.length} 个项目分组，并替换当前浏览器的学习流动数据与项目分组。建议先导出当前数据。</p><div class="button-row"><button class="secondary" data-action="export-all">先导出当前数据</button><button class="primary" id="confirm-restore">确认替换并恢复</button></div>`);
   $('#confirm-restore').onclick=()=>{if(busy){toast('请等当前接口返回后再恢复。');return}if(workspaceSidebar.restoreData(workspace)===false)return;state=clean;activeSession=null;sessionPool.clear();sessionDrafts.clear();window.LearnFlowComposer?.reset();save();settingsUI.applyAppearance();$('#modal').close();render();toast('备份已恢复。导入策略仍应由你审阅。');};
  }catch(e){toast('恢复失败：'+e.message);}
 };picker.click();
}
function importJSON(kind){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files[0];if(!file)return;if(file.size>500000){toast('文件超过 500 KB，请精简后再导入。');return}try{const data=JSON.parse(await file.text());if(kind==='project'){if(!Array.isArray(data.tasks)||data.tasks.length>100)throw Error('需要包含不超过100个任务的项目包');const tasks=data.tasks.map((t,i)=>{if(typeof t.title!=='string'||!['todo','doing','done'].includes(t.status))throw Error('任务格式无效');return{id:`task-${Date.now()}-${i}`,title:t.title.slice(0,160),owner:String(t.owner||'').slice(0,60),evidence:String(t.evidence||'').slice(0,200),status:t.status}});state.tasks.push(...tasks);save();render();toast(`已导入 ${tasks.length} 个任务到本机。`);}else{const list=Array.isArray(data)?data:[data];if(!list.length||list.length>50)throw Error('请一次导入 1–50 张策略');const imported=list.map((c,i)=>{if(typeof c.title!=='string'||typeof c.instructions!=='string'||!['exam','self','project','all'].includes(c.scene))throw Error('需要 title、instructions 和有效 scene');return{id:`custom-${Date.now()}-${i}`,title:c.title.slice(0,60),instructions:c.instructions.slice(0,8000),description:String(c.description||'导入的学习策略').slice(0,160),scene:c.scene,category:LF_SCENES[c.scene]?.title||'交流风格',tags:Array.isArray(c.tags)?c.tags.slice(0,6).map(t=>String(t).slice(0,30)):['导入策略'],icon:'layers',color:['orange','green','blue','purple'].includes(c.color)?c.color:'orange',source:'本机导入 · 请审阅指令'}});state.custom.push(...imported);save();render();toast(`已导入 ${imported.length} 张策略，审阅后可自行启用。`);}}catch(e){toast('导入失败：'+e.message);}};input.click();}
const workspaceSidebar=window.LearnFlowSidebar.create({esc,icon,toast,getSessions:()=>allSessions().map(s=>({...s,title:sessionTitle(s)})),getActiveId:()=>chatPage()?activeSession?.id:null,onOpenSession:openSession,onNewSession:()=>{if(busy){toast('先停止当前回答，再开始新对话。');return null;}startSession(state.scene);return activeSession.id;},onChange:()=>{}});
const teacherDemo=window.LearnFlowTeacher.create({esc,icon,toast,getSessions:()=>allSessions(),getConnectionStatus:()=>window.LearnFlowComposer.connectionStatus(),requestAI:async({purpose,prompt,signal})=>{
 if(busy)throw Error('先等待当前请求结束，再生成教学草稿。');
 if(prompt.length>23000)throw Error('这份学习包太长，请先减少要评价的对话片段。');
 busy=true;
 const deadline=AbortSignal.timeout(125000),requestSignal=signal?AbortSignal.any([signal,deadline]):deadline;
 try{
  if(!(await window.LearnFlowConnection.health())?.configured)throw Error('请先连接模型。');
  requestSignal.throwIfAborted();
  const data=await requestChat({purpose:purpose==='assignment'?'teacher-assignment':'teacher-assessment',model:window.LearnFlowComposer.model(),messages:[{role:'user',content:prompt}],preferences:{style:'plain',memory:false},scene:'self'},requestSignal,()=>{});
  requestSignal.throwIfAborted();
  if(data.status!=='completed'||!data.reply?.trim())throw Error('模型尚未完成教学草稿。');
  window.LearnFlowComposer.success(data.model);return {text:data.reply,usage:data.usage,receipt:data.receipt};
 }catch(e){
  if(signal?.aborted)throw new DOMException('已停止生成，原来的草稿仍保留。','AbortError');
  if(deadline.aborted)e=Error('这次教学草稿等待太久，已停止请求。原来的内容仍保留，可以重试或换一个模型。');
  window.LearnFlowComposer.failure(e.message);throw e;
 }finally{busy=false;}
}});
const gallery=window.LearnFlowGallery.create({esc,icon,getState:()=>state});
const experience=window.createLearningExperience({isBusy:()=>busy,getState:()=>state,save,esc,showModal,modalHead,toast,navigate,render,getSession:ensureSession,persistSession,startSession,activeCards,sendChat});
const settingsUI=window.LearnFlowSettings.create({getState:()=>state,save,toast,icon,esc,backTarget:()=>activeSession?.messages.length?'session':'home',views:{preferences:settingsView,connectors:connectorsView,memory:memoryView,mine:mineView,teacher:teacherView,about:aboutView}});
window.addEventListener('learnflow-qq-task',e=>{const content=e.detail?.content;if(typeof content!=='string')return;if(busy){toast('先停止当前回答，再接收这条 QQ 学习任务。');return;}startSession(state.scene);window.LearnFlowComposer?.setDraft(content);setTimeout(()=>{window.LearnFlowComposer?.mount(mode,busy);$('#chat-input')?.focus();},0);toast('QQ 学习任务已放入输入框，检查后再发送。');});
document.addEventListener('keydown',e=>{if(e.target.id==='home-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();startSession(state.scene,e.target.value.trim());}if(e.target.id==='chat-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(!busy)sendChat(e.target.value);}});

document.addEventListener('submit',e=>{if(e.target.id==='rename-chat-form'){e.preventDefault();const s=ensureSession();s.title=new FormData(e.target).get('title').trim();persistSession(s);$('#modal').close();render();}});
document.addEventListener('click',e=>{if(!e.target.closest('.sidebar-bottom'))closeProfile();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeProfile();if((e.ctrlKey||e.metaKey)&&!e.altKey){if(e.key===','){e.preventDefault();navigate('settings/general');}if(e.key.toLowerCase()==='k'){e.preventDefault();actions['new-session']();setTimeout(()=>$('#chat-input')?.focus(),30);}if(e.key.toLowerCase()==='f'&&!$('#modal').open){e.preventDefault();searchChats();}}});
window.addEventListener('hashchange',render);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});render();if(!state.onboarded&&!location.hash.startsWith('#pair='))setTimeout(()=>experience.onboarding(),400);
})();
